        ORDER BY o.OrderDate DESC
        """;

    public static async Task<IReadOnlyList<CustomerOrdersRow>> GetCustomerOrdersAsync(this IDbConnection db, int customerId, decimal minTotal, CancellationToken ct = default) =>
